export default staticArticles;

export const ARTICLE_CATEGORIES = [
  "All",
  ...Array.from(new Set(staticArticles.map((a) => a.category))),
];

export function getArticleBySlug(slug) {
  return staticArticles.find((a) => a.slug === slug) || null;
}

export function getArticleById(id) {
  return staticArticles.find((a) => a._id === id) || null;
}

// Newest first, optionally limited (used by the homepage latest-content section).
export function getLatestArticles(limit) {
  const sorted = [...staticArticles].sort(
    (a, b) => new Date(b.datePublished) - new Date(a.datePublished)
  );
  return typeof limit === "number" ? sorted.slice(0, limit) : sorted;
}
